<div class="admin-title"><h1><?= $item?'Edit':'Tambah' ?> Iuran Warga</h1><a href="<?= site_url('admin/dues') ?>">&larr; Kembali</a></div><?php if($error): ?><div class="error"><?= html_escape($error) ?></div><?php endif; ?><form class="panel form-panel" method="post"><label>Warga<select name="citizen_id" required><option value="">Pilih warga</option><?php foreach($citizens as $citizen): ?><option value="<?= (int)$citizen['id'] ?>" <?= ($item['citizen_id']??0)==$citizen['id']?'selected':'' ?>><?= html_escape($citizen['display_name']) ?></option><?php endforeach; ?></select></label><div class="form-grid"><label>Periode<input type="month" name="period" required value="<?= html_escape($item['period']??date('Y-m')) ?>"></label><label>Kategori<input name="category" required value="<?= html_escape($item['category']??'Iuran lingkungan') ?>"></label><label>Tagihan (Rp)<input type="number" name="amount_due" min="0" step="1" required value="<?= html_escape($item['amount_due']??0) ?>"></label><label>Sudah dibayar (Rp)<input type="number" value="<?= html_escape($item['amount_paid']??0) ?>" readonly><small>Pembayaran diperbarui melalui verifikasi di menu Iuran Warga.</small></label></div><label>Catatan internal<input name="note" value="<?= html_escape($item['note']??'') ?>"></label><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><button class="button" type="submit">Simpan iuran</button></form>
